#!/usr/bin/env python3
"""Modernized climate data analysis script."""

import configparser
from pathlib import Path

import pandas as pd

BASE_DIR = Path(__file__).resolve().parent / "climate_analyzer"
DATA_PATH = BASE_DIR / "sample_data" / "climate_data.csv"
CONFIG_PATH = BASE_DIR / "config.ini"


def load_config(config_path: Path) -> configparser.ConfigParser:
    config = configparser.ConfigParser()
    config.read(config_path, encoding="utf-8")
    return config


def load_temperature_data(csv_path: Path) -> pd.DataFrame:
    return pd.read_csv(csv_path, parse_dates=["date"], encoding="utf-8")


def main() -> None:
    load_config(CONFIG_PATH)
    df = load_temperature_data(DATA_PATH)

    for station_id, group in df.groupby("station_id"):
        mean_temp = group["temperature"].mean()
        print(f"Station {station_id} mean temperature: {mean_temp:.1f}°C")


if __name__ == "__main__":
    main()

